using Bodoconsult.App.Wpf.Charting.Models;
using System.Windows.Media.Media3D;

namespace Bodoconsult.App.Wpf.Charting.Test.Utilities;

public class DataUtility
{
    public static void Peak3D(ChartStyle cs)
    {

        var ds = cs.DataSeries;

        cs.Xmin = -3;
        cs.Xmax = 3;
        cs.Ymin = -3;
        cs.Ymax = 3;
        cs.Zmin = -8;
        cs.Zmax = 8;
        cs.XTick = 1;
        cs.YTick = 1;
        cs.ZTick = 4;

        ds.XLimitMin = cs.Xmin;
        ds.YLimitMin = cs.Ymin;
        ds.XSpacing = 0.1;
        ds.YSpacing = 0.1;
        ds.XNumber = Convert.ToInt16((cs.Xmax - cs.Xmin) / ds.XSpacing) + 1;
        ds.YNumber = Convert.ToInt16((cs.Ymax - cs.Ymin) / ds.YSpacing) + 1;

        var pts = new Point3D[ds.XNumber, ds.YNumber];
        for (var i = 0; i < ds.XNumber; i++)
        {
            for (var j = 0; j < ds.YNumber; j++)
            {
                var x = ds.XLimitMin + i * ds.XSpacing;
                var y = ds.YLimitMin + j * ds.YSpacing;
                var z = 3 * Math.Pow((1 - x), 2) * Math.Exp(-x * x - (y + 1) * (y + 1)) - 10 *
                    // ReSharper disable once PossibleLossOfFraction
                    (0.2 * x - Math.Pow(x, 3) - Math.Pow(y, 5)) * Math.Exp(-x * x - y * y) - 1 / 3 *
                    Math.Exp(-(x + 1) * (x + 1) - y * y);
                pts[i, j] = new Point3D(x, y, z);
            }
        }
        ds.PointArray = pts;
    }

    public static void Sinc3D(ChartStyle cs)
    {

        var ds = cs.DataSeries;

        cs.Xmin = -8;
        cs.Xmax = 8;
        cs.Ymin = -8;
        cs.Ymax = 8;
        cs.Zmin = -0.5f;
        cs.Zmax = 1;
        cs.XTick = 4;
        cs.YTick = 4;
        cs.ZTick = 0.5f;

        ds.XLimitMin = cs.Xmin;
        ds.YLimitMin = cs.Ymin;
        ds.XSpacing = 0.5;
        ds.YSpacing = 0.5;
        ds.XNumber = Convert.ToInt16((cs.Xmax - cs.Xmin) / ds.XSpacing) + 1;
        ds.YNumber = Convert.ToInt16((cs.Ymax - cs.Ymin) / ds.YSpacing) + 1;

        var pts = new Point3D[ds.XNumber, ds.YNumber];
        for (var i = 0; i < ds.XNumber; i++)
        {
            for (var j = 0; j < ds.YNumber; j++)
            {
                var x = ds.XLimitMin + i * ds.XSpacing;
                var y = ds.YLimitMin + j * ds.YSpacing;
                var r = Math.Sqrt(x * x + y * y) + 0.000001;
                var z = Math.Sin(r) / r;
                pts[i, j] = new Point3D(x, y, z);
            }
        }
        ds.PointArray = pts;
    }

